SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsRegisterDeviceResponse
{
    boolean success;
    str     errorCode;
    str     message;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

/// <summary>
/// NO_LICENSE, LICENSE_INVALID, LICENSE_EXPIRED (re-checked here too - see
/// HSMobileOpsLicenseService::registerDevice's own doc) or DEVICE_LIMIT_REACHED.
/// </summary>
[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}
